function netPingForEntity(e){
  if(!e||e.hp<=0||e.kind==='peddler'||!G||G.ents.indexOf(e)<0)return null;
  var i,p,now=Date.now();
  for(i=(NET.pings||[]).length-1;i>=0;i--){
